const settings = $('News Settings').first().json;
const urls = String(settings.newsSources || '')
  .split(',')
  .map(s => s.trim())
  .filter(Boolean);

return urls.map((url, index) => ({
  json: {
    feedUrl: url,
    sourceIndex: index + 1
  }
}));

const maxArticles = Number($('News Settings').first().json.maxArticles || 15);
const items = $input.all();

const seen = new Set();
const articles = [];

for (const item of items) {
  const j = item.json || {};
  const title = String(j.title || j.name || '').trim();
  const link = String(j.link || j.guid || '').trim();
  const description = String(j.contentSnippet || j.content || j.description || '').replace(/<[^>]*>/g, ' ').trim();
  const pubDate = j.isoDate || j.pubDate || j.date || new Date().toISOString();

  if (!title) continue;

  const key = (link || title).toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);

  articles.push({
    title,
    link,
    description: description.slice(0, 1200),
    pubDate,
    source: String(j.creator || j.author || j.source || 'RSS News')
  });
}

articles.sort((a, b) => new Date(b.pubDate) - new Date(a.pubDate));

return articles.slice(0, maxArticles).map((article, index) => ({
  json: {
    rank: index + 1,
    ...article
  }
}));

const articles = $input.all().map(i => i.json);

const articleText = articles.map((a, i) =>
  `ARTICLE ${i + 1}
Title: ${a.title}
Source: ${a.source}
Published: ${a.pubDate}
URL: ${a.link}
Description: ${a.description}`
).join('\n\n');

return [{
  json: {
    articleCount: articles.length,
    articles,
    aiPrompt: `Create a concise Daily News Digest from the following news articles.

Rules:
1. Group stories into: World, India, Technology, Business, Science, and Other.
2. Do not invent facts.
3. Summarize each important story in 2-3 sentences.
4. Mention the source.
5. Include the original URL.
6. Remove obvious duplicates.
7. If a category has no relevant story, omit it.
8. Start with 3-5 key highlights.
9. Use simple, professional English.
10. Return only the finished digest in clean Markdown.

NEWS:
${articleText}`
  }
}];

const prompt = $json.aiPrompt || '';
const articles = $json.articles || [];

const lines = articles.map((a, i) =>
  `${i + 1}. ${a.title} — ${a.source} — ${a.link}`
).join('\n');

return [{
  json: {
    ...$json,
    digest: `# Daily News Digest

## Key Highlights
${articles.slice(0, 5).map((a, i) => `${i + 1}. **${a.title}** — ${a.source}`).join('\n')}

## News Stories
${lines}

## Summary
${prompt}

_Note: This workflow currently prepares the digest from RSS feeds. Connect an AI model node after this step to generate AI-written summaries._`
  }
}];

const data = $json;
const date = new Date().toLocaleDateString('en-IN', {
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

return [{
  json: {
    date,
    title: $('News Settings').first().json.digestTitle || 'Daily News Digest',
    articleCount: data.articleCount || 0,
    digest: data.digest || 'No news available today.'
  }
}];
